use snm02_improper_handling::{export_ticket_record, Ticket};

#[test]
fn valid_record_succeeds() {
    let ticket = Ticket {
        id: 42,
        subject: "Cannot access VPN".to_string(),
        requester_email: Some("alice@snemeis.example".to_string()),
    };

    let exported = export_ticket_record(&ticket).expect("valid record should export");
    assert_eq!(exported, "42,alice@snemeis.example,Cannot access VPN");
}

#[test]
fn missing_required_field_fails_safely_in_secure_version() {
    let ticket = Ticket {
        id: 43,
        subject: "Billing question".to_string(),
        requester_email: None,
    };

    let result = std::panic::catch_unwind(|| export_ticket_record(&ticket));
    assert!(
        result.is_ok(),
        "secure version should not panic when requester_email is missing"
    );

    let export_result = result.unwrap();
    assert!(
        export_result.is_err(),
        "secure version should return an error for missing requester_email"
    );
}

#[test]
fn missing_required_field_does_not_panic_in_secure_version() {
    let ticket = Ticket {
        id: 44,
        subject: "Laptop replacement".to_string(),
        requester_email: None,
    };

    let result = std::panic::catch_unwind(|| export_ticket_record(&ticket));
    assert!(
        result.is_ok(),
        "secure version should avoid panic-based error handling"
    );
}

#[test]
fn empty_required_field_fails_safely_in_secure_version() {
    let ticket = Ticket {
        id: 45,
        subject: "Reset MFA".to_string(),
        requester_email: Some("   ".to_string()),
    };

    let result = std::panic::catch_unwind(|| export_ticket_record(&ticket));
    assert!(
        result.is_ok(),
        "secure version should not panic on empty requester_email"
    );

    let export_result = result.unwrap();
    assert!(
        export_result.is_err(),
        "secure version should reject empty requester_email"
    );
}

#[test]
fn malformed_requester_email_fails_safely_in_secure_version() {
    let ticket = Ticket {
        id: 46,
        subject: "Security review follow-up".to_string(),
        requester_email: Some("alice-at-snemeis.example".to_string()),
    };

    let result = std::panic::catch_unwind(|| export_ticket_record(&ticket));
    assert!(
        result.is_ok(),
        "secure version should not panic on malformed requester_email"
    );

    let export_result = result.unwrap();
    assert!(
        export_result.is_err(),
        "secure version should reject malformed requester_email instead of exporting it"
    );
}
